  22   appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
  23   measurementId: process.env.NEXT_PUBLIC_FIREBASE_MEASUREMENT_ID,
  24 };
  25 
  26 // Validate that all required environment variables are present
  27 const requiredVars = [
  28   'NEXT_PUBLIC_FIREBASE_API_KEY',
  29   'NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN',
  30   'NEXT_PUBLIC_FIREBASE_DATABASE_URL',
